import {Chess} from './vendor/chess.js';
import {names,values,opposite,moveEvidence,hanging,pins} from './tactics.js';
const piece=p=>`${names[p.type]} in ${p.square}`;
const target=p=>(p.type==='q'||p.type==='r'?'la ':'il ')+piece(p);
export function briefComment(move,before,after,grade,tone='warm',context={}){
 const e=moveEvidence(move,after),c=e.c;
 if(c.isCheckmate())return 'Scacco matto: hai chiuso la partita! Il re avversario non ha più risposte legali.';
 if(c.isStalemate())return 'È stallo: il re avversario non è sotto scacco e non ha mosse legali. La partita è patta.';
 if(!grade)return 'Mossa registrata. Non ho una valutazione sufficiente per giudicarla.';
 const negative=grade.loss>.05;let fact='';const seed=[...move.after].reduce((n,c)=>Math.imul(n^c.charCodeAt(0),16777619),2166136261)>>>0;const pick=items=>{const options=items.filter(t=>!context.previous?.startsWith(t));return (options.length?options:items)[seed%(options.length||items.length)]};
 if(!negative&&after?.mate!=null&&after.cp*(move.color==='w'?1:-1)<0)return 'La posizione resta difficile: il motore vede ancora un matto contro il tuo re. Questa mossa non basta a eliminare la minaccia.';
 if(negative){
  if(after?.mate!=null&&after.cp*(move.color==='w'?1:-1)<0)fact=(before?.mate!=null&&before.cp*(move.color==='w'?1:-1)<0?'La minaccia di matto era già presente e rimane.':'Il motore vede ora una minaccia di matto contro il tuo re.')+' Prima di pensare al piano, controlla gli scacchi avversari.';
  else if(e.reply?.captured){const r=e.reply,capturedSquare=r.flags.includes('e')?r.to[0]+(r.color==='w'?'5':'4'):r.to,undefended=!c.isAttacked(capturedSquare,move.color);fact=`${r.captured==='q'||r.captured==='r'?'La tua':'Il tuo'} ${names[r.captured]} in ${capturedSquare} ${undefended?'è attaccato e non è difeso':'può essere catturato dal '+names[r.piece]+' in '+r.from}. ${undefended?'Controlla quali pezzi rimangono scoperti dopo la tua mossa.':'Conta anche le ricatture prima di scegliere uno scambio.'}`}
  else if(e.enemyFork.length>=2)fact=`Ora l’avversario può creare un doppio attacco contro ${target(e.enemyFork[0])} e ${target(e.enemyFork[1])}. Controlla le minacce prima del tuo piano.`;
  else if(e.enemyPins.length){const p=e.enemyPins[0];fact=`${p.pinned.type==='q'||p.pinned.type==='r'?'La tua':'Il tuo'} ${piece(p.pinned)} è inchiodato al re dal ${names[p.attacker.type]} in ${p.attacker.square}. Non può abbandonare questa linea lasciando il re sotto scacco.`}
  else if(e.loose.length)fact=`${e.loose[0].type==='q'||e.loose[0].type==='r'?'La tua':'Il tuo'} ${piece(e.loose[0])} è attaccato e non è difeso. Controlla se la tua idea compensa questo rischio.`;
  else fact='Il motore preferiva un’altra scelta, ma non ho una causa tattica verificata da indicarti. '+strategyObservation(move)+' Valuta se questo cambio aiuta il tuo piano.';
  return (tone==='direct'?'Da rivedere. ':tone==='quiet'?'Attenzione. ':pick(['Guardiamo cosa è cambiato. ', 'C’è un dettaglio da sistemare. ', 'Questa scelta merita attenzione. ', 'Tieni a mente questo punto. ', 'Qui puoi affinare la tua idea. ']))+fact;
 }
 if(e.fork.length>=2)fact=`Il tuo ${names[move.promotion||move.piece]} in ${move.to} attacca sia ${target(e.fork[0])} sia ${target(e.fork[1])}: un doppio attacco.`;
 else if(e.newPins.length){const p=e.newPins[0];fact=`Hai inchiodato ${target(p.pinned)} al re. Non può lasciare la linea se così espone il re allo scacco.`}
 else if(move.flags.includes('k')||move.flags.includes('q'))fact='Hai arroccato e portato la torre verso il centro. È un buon passo per coordinare i tuoi pezzi.';
 else if(move.captured)fact=`Hai catturato un ${names[move.captured]} in ${move.to} senza peggiorare sensibilmente la posizione. Tieni d’occhio anche i pezzi rimasti sotto attacco.`;
 else {const old=new Chess(move.before),was=hanging(old,move.color).find(p=>p.square===move.from);if(was&&!c.isAttacked(move.to,opposite(move.color)))fact=`Hai spostato il ${names[move.piece]} da ${move.from}, dove era attaccato e senza difesa, a una casa non attaccata.`;
 else if(['n','b'].includes(move.piece)&&move.from[1]===(move.color==='w'?'1':'8')){const centers=['d4','e4','d5','e5'].filter(sq=>c.attackers(sq,move.color).includes(move.to));fact=`Hai sviluppato il ${names[move.piece]} in ${move.to}${centers.length?', da dove controlla '+centers.join(' e '):'. Ora può partecipare al piano'}.`}
 else if(c.isCheck())fact='Hai dato scacco senza peggiorare sensibilmente la valutazione. Il re avversario deve rispondere alla minaccia.';
 else if(['d4','e4','d5','e5'].includes(move.to))fact=`Con il ${names[move.piece]} in ${move.to} occupi una casa centrale. Ora pensa a come far collaborare gli altri pezzi con questo.`;
 else fact=strategyObservation(move)+' La valutazione non peggiora sensibilmente: puoi continuare a costruire la tua idea.';}
 return (tone==='direct'?'Buona scelta. ':tone==='quiet'?'Bene. ':pick(['Bene, un passo utile. ', 'Buona scelta per questa posizione. ', 'Questa idea regge al controllo. ', 'Bene, hai mantenuto l’equilibrio della posizione. ', 'Continua così, con attenzione. ']))+fact;
}
export function strategicHint(c){if(c.isCheck())return 'Il tuo re è sotto scacco: prima risolvi questo problema.';const loose=hanging(c,c.turn());if(loose.length)return `Controlla il tuo ${piece(loose[0])}: è attaccato e non è difeso. Come puoi gestire la minaccia?`;const pin=pins(c,opposite(c.turn()))[0];if(pin)return `Il tuo ${piece(pin.pinned)} è inchiodato al re: tienine conto quando conti i difensori.`;const attacked=c.board().flat().filter(p=>p&&p.color===c.turn()&&p.type!=='k'&&c.isAttacked(p.square,opposite(c.turn())));if(attacked.length)return `Controlla attaccanti e difensori del tuo ${piece(attacked.sort((a,b)=>values[b.type]-values[a.type])[0])}.`;return c.moveNumber()<12?'Quale pezzo deve ancora entrare in gioco? Pensa anche alla sicurezza del re.':'Qual è il tuo pezzo meno attivo? Cerca un modo per migliorarlo senza trascurare le minacce.'}

export function strategyObservation(move){const c=new Chess(move.after),old=new Chess(move.before),color=move.color,centers=['d4','e4','d5','e5'];const count=pos=>centers.filter(s=>pos.isAttacked(s,color)).length,delta=count(c)-count(old);if(delta>0)return `Ora controlli ${count(c)} delle quattro case centrali, ${delta} in più di prima.`;if(delta<0)return `Dopo la mossa controlli ${count(c)} delle quattro case centrali, ${-delta} in meno di prima.`;if(move.piece==='p')return 'Hai cambiato la struttura dei pedoni: questa spinta non può essere annullata.';if(move.piece==='k')return 'Hai cambiato la posizione del re: confronta la sua attività con gli attacchi avversari.';if(move.piece==='r'){const pawns=c.board().flat().filter(p=>p?.type==='p'&&p.square[0]===move.to[0]);return pawns.length?'La torre è su una colonna che contiene ancora pedoni.':'La torre è su una colonna aperta, senza pedoni.'}return `Hai riposizionato il ${names[move.piece]}: chiediti quali compiti può svolgere da ${move.to}.`}
export function coachAnswer(c,question,color=c.turn(),lastGrade=null){
 if(c.isGameOver())return c.isCheckmate()?'La partita è finita per scacco matto. Nel riepilogo puoi individuare un solo tema su cui lavorare alla prossima.':'La partita è terminata in patta. Guarda se il risultato era inevitabile oppure se avevi ancora margine prima della posizione finale.';
 if(question==='last'){if(!lastGrade?.move)return 'Appena avrai giocato una mossa, ne discuteremo qui. Per ora scegli liberamente il tuo piano.';return 'Sulla tua ultima mossa: '+briefComment(lastGrade.move,lastGrade.reviewBefore,lastGrade.after,lastGrade,'direct')}
 if(c.turn()!==color)return 'Aspettiamo la risposta dell’avversario: poi ragioniamo sulla posizione che avrai davanti.';
 if(c.isCheck())return 'Il tuo re è sotto scacco. Il primo compito è risolverlo: valuta cattura, interposizione o spostamento del re, secondo le mosse legali disponibili.';
 const pieces=c.board().flat().filter(p=>p?.color===color),enemy=opposite(color);
 if(question==='threat'){const loose=hanging(c,color);if(loose.length)return `Sono attaccati e senza difesa: ${loose.slice(0,3).map(piece).join(', ')}. Non significa che ogni cattura convenga: controlla anche eventuali compensi e ricatture.`;const attacked=pieces.filter(p=>p.type!=='k'&&c.isAttacked(p.square,enemy));return attacked.length?`Sono sotto attacco ${attacked.slice(0,3).map(piece).join(', ')}, ma hanno difensori. Conta gli scambi prima di decidere se intervenire.`:'Non vedo tuoi pezzi attaccati in questo momento. Puoi dedicarti al piano, controllando comunque le minacce che la prossima mossa avversaria potrebbe creare.'}
 if(question==='king'){const king=pieces.find(p=>p.type==='k'),file=king.square.charCodeAt(0),rank=+king.square[1];const adjacent=[];for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){const x=file+dx,y=rank+dy;if((dx||dy)&&x>=97&&x<=104&&y>=1&&y<=8){const sq=String.fromCharCode(x)+y;if(c.isAttacked(sq,enemy))adjacent.push(sq)}}return adjacent.length?`Il re in ${king.square} non è sotto scacco, ma queste case vicine sono controllate dall’avversario: ${adjacent.join(', ')}. Considerale quando valuti vie di fuga e difensori.`:`Il re in ${king.square} non è sotto scacco e le case adiacenti non risultano attaccate. Non basta a garantire sicurezza: osserva anche linee aperte e possibili scacchi.`}
 if(question==='activity'){const undeveloped=pieces.filter(p=>'nb'.includes(p.type)&&p.square[1]===(color==='w'?'1':'8'));if(undeveloped.length)return `Hai ancora ${undeveloped.map(piece).join(' e ')} sulla prima traversa. Quale può entrare in gioco senza perdere la difesa di qualcosa?`;return 'I pezzi leggeri non sono più sulla prima traversa. Scegli quello con meno compiti utili e valuta come migliorarlo, senza lasciare un bersaglio scoperto.'}
 const pin=pins(c,enemy)[0];if(pin)return `Prima del piano, considera il pezzo inchiodato in ${pin.pinned.square}: non può lasciare scoperto il re. Quali altri pezzi possono aiutarti?`;
 if(hanging(c,color).length)return 'Prima di espandere il tuo piano, c’è un pezzo attaccato e senza difesa. Decidi se proteggerlo, spostarlo o compensare il rischio: l’idea rimane tua.';
 const nonPawns=pieces.filter(p=>p.type!=='p'&&p.type!=='k');return nonPawns.length<=2?'Con pochi pezzi, attività del re e pedoni diventano centrali. Quale dei due aspetti puoi migliorare senza concedere contropiede?':'Scegli un obiettivo concreto: rendere attivo un pezzo, sostenere il centro oppure migliorare la sicurezza del re. Quale risponde meglio a ciò che vedi adesso?';
}
